mapper.update:
UPDATE notification
SET is_read = 1
WHERE id = #{id}

mapper.select:
SELECT * FROM notification
WHERE user_id = #{userId}
ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT * FROM notification
WHERE activity_id = #{activityId}
ORDER BY create_time DESC

SELECT * FROM notification
WHERE user_id = #{userId}

    AND id < #{lastId}

ORDER BY id DESC
LIMIT #{size}

SELECT * FROM notification
ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT n.* FROM notification n
INNER JOIN (
    SELECT MIN(id) AS id FROM notification
    WHERE type = #{type}
    GROUP BY title, content
) grp ON n.id = grp.id
ORDER BY n.create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM (
    SELECT title, content FROM notification
    WHERE type = #{type}
    GROUP BY title, content
) AS distinct_announcements
